import { createHmac } from 'node:crypto'

export interface ConnectorConfig {
  intercomClientSecret: string
  zendeskSubdomain: string
  zendeskAccessToken: string
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  type: string
  topic: string
  data: {
    item: {
      type: string
      id: string
      url: string
    }
    tag?: {
      name: string
    }
  }
}

export interface ZendeskTicketResponse {
  ticket: {
    id: number
    subject: string
    description: string
  }
}

export interface HandleResult {
  ticketId: number
  subject: string
}

function verifySignature(payload: string, signature: string, secret: string): boolean {
  const expected = createHmac('sha1', secret).update(payload).digest('hex')
  return signature === expected
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.data?.item) {
    throw new Error('Missing required field: data.item')
  }
  if (payload.data.item.type !== 'conversation') {
    throw new Error('Webhook item type is not a conversation')
  }
  if (!payload.data.item.id) {
    throw new Error('Missing required field: data.item.id')
  }
  if (!payload.data.item.url) {
    throw new Error('Missing required field: data.item.url')
  }
  if (payload.topic !== 'conversation_part.tag.created') {
    throw new Error(`Unexpected webhook topic: ${payload.topic}`)
  }
  if (!payload.data.tag || payload.data.tag.name !== 'refund') {
    throw new Error(`Tag is not 'refund': ${payload.data.tag?.name ?? 'missing'}`)
  }

  const conversationId = payload.data.item.id
  const conversationUrl = payload.data.item.url

  const ticketPayload = {
    ticket: {
      subject: conversationUrl,
      comment: {
        body: `Intercom conversation ID: ${conversationId}`
      }
    }
  }

  const url = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.zendeskAccessToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(ticketPayload)
  })

  if (!response.ok) {
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} at ${url}`)
  }

  const result = await response.json() as ZendeskTicketResponse
  return {
    ticketId: result.ticket.id,
    subject: result.ticket.subject
  }
}

