    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer test-token')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    await handle(basePayload, { ...baseConfig, fetch })
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-token')
  })

  it('maps conversation.url to subject and conversation.id to description', async () => {
    const customPayload: IntercomWebhookPayload = {
      ...basePayload,
      data: {
        ...basePayload.data,
