  it('throws on non-2xx response from Zendesk', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow('Zendesk API error: 401 Unauthorized at https://test-subdomain.zendesk.com/api/v2/tickets.json')
